gv=np.zeros(X0.shape[1]); gv[0]=n; gv[1:1+ncen]=(Z[:,:ncen]*m[:,None]).sum(0); gv/=n
MACT={k:Y[k][act].mean() for k in Y}
def stat(perm, YY):
    X=dcols(perm); b,_=solve(X,YY)
    return {q:gv@b[q] for q in YY}
S=400; t0=time.perf_counter()
