    sc=100.0/MACT[k]; q=(gv@b0[k])*sc
    sc_=lambda E: np.sqrt(((E-E.mean())**2).sum()/len(E))*sc
    s1=sc_(Ec[k]); s2=sc_(Er[k])
    print(f"  {k:<10}{q:>+10.3f}{s1:>11.3f}{s2:>10.3f}{q/s1:>8.2f}{q/s2:>9.2f}")
print("\n=== EXACT randomization inference: where does the real assignment sit? ===")
Yc={q:Y[q] for q in Y}
real={q:(gv@b0[q]) for q in Y}
null={q:np.array([stat(p,Yc)[q] for p in rand]) for q in Y}
for k in ("app_rate","cert_rate","hours_rate"):
    d=null[k]; r=real[k]
    p2=(np.abs(d-d.mean())>=abs(r-d.mean())).mean()
    print(f"  {k:<12} statistic {r:>+9.4f}   null mean {d.mean():>+9.4f} sd {d.std():.4f}"
          f"   two-sided p = {p2:.4f}   -> {'REJECT at 5%' if p2<0.05 else 'no'}")
