import numpy as np, time
z=np.load("/home/claude/mcwchk/cache.npz")
Z=z["Z"].astype(np.float64); rof=z["rof"]; tof=z["tof"]; Wg=z["W"]; ncen=int(z["ncen"]); R=int(z["R"])
Y={k[2:]:z[k] for k in z.files if k.startswith("Y_")}
n=len(rof); rng=np.random.default_rng(7)
ZtZ=Z.T@Z; e,V=np.linalg.eigh(ZtZ); k=e>e.max()*1e-11; ZtZi=(V[:,k]/e[k])@V[:,k].T
ZtY={q:Z.T@Y[q] for q in Y}
def resid(A): return A - Z@(ZtZi@(Z.T@A))
Yr={q:Y[q]-Z@(ZtZi@ZtY[q]) for q in Y}
act=Y["anyapp"]>0; mm=act.astype(float); nact=mm.sum()
gv=np.concatenate([[1.0],(Z[:,:ncen]*mm[:,None]).sum(0)/nact])
MACT={q:Y[q][act].mean() for q in Y}
