def block(perm):
    w=Wg[perm[rof], tof]
    return np.column_stack([w[:,None], Zc*w[:,None]])
def stat(perm, YY, ret_fit=False):
    Wr=resid(block(perm)); G=Wr.T@Wr
    ee,VV=np.linalg.eigh(G); kk=ee>ee.max()*1e-11; Gi=(VV[:,kk]/ee[kk])@VV[:,kk].T
    out={q: gv@(Gi@(Wr.T@YY[q])) for q in YY}
    return (out,Wr,Gi) if ret_fit else out
