fit0={q: Z@(ZtZi@ZtY[q]) + Wr0@(G0i@(Wr0.T@Yr[q])) for q in Y}
U={q:(Y[q]-fit0[q])*hw for q in Y}
Ur={q:U[q]-Z@(ZtZi@(Z.T@U[q])) for q in Y}
